bool ProjectDatabases::validateJsonForCreation(const Json::Value &pJson, std::string &err)
{
    if(pJson.isMember("id"))
    {
        if(!validJsonOfField(0, "id", pJson["id"], err, true))
            return false;
    }
    if(pJson.isMember("project_id"))
    {
        if(!validJsonOfField(1, "project_id", pJson["project_id"], err, true))
            return false;
    }
    if(pJson.isMember("template_kind"))
    {
        if(!validJsonOfField(2, "template_kind", pJson["template_kind"], err, true))
            return false;
    }
    else
    {
        err="The template_kind column cannot be null";
        return false;
    }
    if(pJson.isMember("scope_type"))
    {
        if(!validJsonOfField(3, "scope_type", pJson["scope_type"], err, true))
            return false;
    }
    else
    {
        err="The scope_type column cannot be null";
        return false;
    }
    if(pJson.isMember("source_name"))
    {
        if(!validJsonOfField(4, "source_name", pJson["source_name"], err, true))
            return false;
    }
    if(pJson.isMember("source_path"))
    {
        if(!validJsonOfField(5, "source_path", pJson["source_path"], err, true))
            return false;
    }
    if(pJson.isMember("db_version"))
    {
        if(!validJsonOfField(6, "db_version", pJson["db_version"], err, true))
            return false;
    }
    if(pJson.isMember("is_enabled"))
    {
        if(!validJsonOfField(7, "is_enabled", pJson["is_enabled"], err, true))
            return false;
    }
    if(pJson.isMember("created_at"))
    {
        if(!validJsonOfField(8, "created_at", pJson["created_at"], err, true))
            return false;
    }
    if(pJson.isMember("updated_at"))
    {
        if(!validJsonOfField(9, "updated_at", pJson["updated_at"], err, true))
            return false;
    }
    return true;
}
